#include <bits/stdc++.h>
using namespace std;
#define mod 998244353

int main() {
	// your code goes here
	int t;
	cin >> t;
	
	while(t--){
	    int n;
	    cin >> n;
	    
	    vector<int>arr(n+1);
	    vector<int>start(n+2 , 0) , ord(n);
	    
	    for(int i = 1 ; i <= n ; i++){
	        cin >> arr[i];
	        start[arr[i]+1]++;
	    }
	    
	    for(int v = 1 ; v <= n + 1 ; v++)
	        start[v] += start[v-1];
	    
	    
	        vector<int>pos = start;
	        for(int i = 1 ; i <= n ; i++){
	            ord[pos[arr[i]]++] = i;
	        }
	    
	    
	    vector<int>dl(n+2 , 0) , dr(n+2 , 0);
	    vector<int>nl(n+2 , 0) , nr(n+2 , 0);
	    
	    dr[0] = 1;
	    
	    for(int s = 1 ; s <= n ; s++){
	        int low = start[s] , high = start[s+1];
	        
	        fill(nl.begin() , nl.end() , 0);
	        fill(nr.begin() , nr.end() , 0);
	        
	        for(int l = 0 ; l <= s  ; l++){
	            int r = s-l;
	            int vl = 0 , vr = 0;
	            
	            if(l >= 1)
	               vl = (dl[l-1] + dr[l-1]) % mod;
	               
	            if(r >= 1)
	               vr = (dl[l] + dr[l]) % mod;
	               
	            if(vl == 0 && vr == 0) continue;
	                bool okl = true , okr = true;
	                
	                for(int q = low ; q < high && (okl || okr) ; q++){
	                    int i = ord[q];
	                    
	                    if(i <= l){
	                        bool g = (s == (n+i)/2);
	                        okr = okr && g;
	                        okl = okl && (g || (i == l && i == 1));
	                    }
	                    else if(i >= n - r + 1){
	                        bool g = (s == n - i / 2);
	                        okl = okl && g;
	                        okr = okr && (g || ( i == n-r+1 && i == n));
	                    }
	                    else{
	                        int j = (i+1) / 2;
	                        int u = (n-i+2)/2;
	                        
	                        okl = okl && (l == j);
	                        okr = okr && (r == u);
	                    }
	                }
	                
	                nl[l] = okl ? vl : 0;
	                nr[l] = okr ? vr : 0;
	            
	        }
	        
	        swap(dl , nl);
	        swap(dr , nr);
	    }
	    
	    long long res = 0;
	    
	    for(int l = 1 ; l <= n ; l++){
	        res = (res + dl[l]) % mod;
	    }
	    
	    cout << res  << endl;
	}

}
